import React, { useState } from 'react';
import axios from 'axios';
import * as cheerio from 'cheerio';
import './NewsScraper.css';

const NewsScraper = () => {
  const [url, setUrl] = useState('');
  const [news, setNews] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [filter, setFilter] = useState('');
  const [filterInput, setFilterInput] = useState('');
  const [sortBy, setSortBy] = useState('date');

  const scrapeNews = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await axios.post('http://localhost:5000/api/scrape', { url });
      setNews(response.data.news);
    } catch (err) {
      setError('Error scraping the website. Please check the URL and try again.');
    }
    setLoading(false);
  };

  const applyFilter = () => {
    setFilter(filterInput);
  };

  const filteredAndSortedNews = news
    .filter(item => 
      filter === '' || 
      item.headline.toLowerCase().includes(filter.toLowerCase()) ||
      item.author.toLowerCase().includes(filter.toLowerCase())
    )
    .sort((a, b) => {
      if (sortBy === 'date') {
        return new Date(b.date) - new Date(a.date);
      }
      if (sortBy === 'relevance' && filter) {
        // Simple relevance: count keyword matches in headline/author
        const aScore = (a.headline + ' ' + a.author).toLowerCase().split(filter.toLowerCase()).length - 1;
        const bScore = (b.headline + ' ' + b.author).toLowerCase().split(filter.toLowerCase()).length - 1;
        return bScore - aScore;
      }
      return a.headline.localeCompare(b.headline);
    });

  return (
    <div className="news-scraper">
      <div className="controls">
        <input
          type="text"
          value={url}
          onChange={(e) => setUrl(e.target.value)}
          placeholder="Enter website URL to scrape"
          className="url-input"
        />
        <button 
          onClick={scrapeNews} 
          disabled={loading || !url}
          className="scrape-button"
        >
          {loading ? 'Scraping...' : 'Scrape News'}
        </button>
      </div>

      <div className="filters">
        <input
          type="text"
          value={filterInput}
          onChange={(e) => setFilterInput(e.target.value)}
          placeholder="Filter by keyword"
          className="filter-input"
        />
        <button
          onClick={applyFilter}
          className="scrape-button"
          style={{ minWidth: 90 }}
        >
          Filter
        </button>
        <select 
          value={sortBy} 
          onChange={(e) => setSortBy(e.target.value)}
          className="sort-select"
        >
          <option value="date">Sort by Date</option>
          <option value="title">Sort by Title</option>
          <option value="relevance">Sort by Relevance</option>
        </select>
      </div>

      {error && <div className="error">{error}</div>}

      {loading && (
        <div className="loading">
          <div className="spinner"></div>
          <p>Scraping in progress...</p>
        </div>
      )}

      <div className="news-list">
        {filteredAndSortedNews.map((item, index) => (
          <div key={index} className="news-item">
            <h2>{item.headline}</h2>
            <div className="news-meta">
              <span>By: {item.author}</span>
              <span>Date: {item.date}</span>
              <span>Source: {item.source}</span>
            </div>
            <a href={item.url} target="_blank" rel="noopener noreferrer">
              Read More
            </a>
          </div>
        ))}
      </div>
    </div>
  );
};

export default NewsScraper;
